    tourHistAddDayBody: 'कल लॉग करना भूल गए? कोई भी छूटा दिन भरने के लिए "पिछला दिन जोड़ें" उपयोग करें। कैलेंडर से तारीख चुनें, ग्राहक संख्या और बिक्री दर्ज करें।',
    tourHistTrendsTitle: 'मासिक रुझान',
    tourHistTrendsBody: 'महीने के हिसाब से अपना डेटा देखें — प्रति दिन औसत ग्राहक, कुल, और हर महीने पिछले से कैसे तुलना करता है।',
    tourHistImportTitle: 'पुराना डेटा आयात करें',
    tourHistImportBody: 'स्प्रेडशीट में रिकॉर्ड हैं? महीनों या वर्षों का इतिहास एक बार में लाने के लिए यहाँ CSV अपलोड करें। Ope पहले फ़ाइल का प्रीव्यू दिखाता है।',
    tourManageProductsTitle: 'मेरे उत्पाद',
    tourManageProductsBody: 'यहाँ जो कुछ भी आप बेचते हैं वो जोड़ें — बस एक नाम और इकाई से शुरू करें। वैकल्पिक रूप से सप्लायर लीड टाइम, वर्तमान स्टॉक और शेल्फ लाइफ जोड़ें।',
    tourManageRegularsTitle: 'मेरे नियमित ग्राहक',
    tourManageRegularsBody: 'अपने वफादार ग्राहकों को "नियमित" के रूप में जोड़ें, उनकी यात्रा आवृत्ति और समय के साथ आपके व्यापार के लिए उनके मूल्य को ट्रैक करने के लिए।',
    tourManageRecurringTitle: 'आवर्ती पैटर्न',
    tourManageRecurringBody: 'हर रविवार स्कूल का दौरा है? हर महीने का बाज़ार का दिन? यहाँ घोषित करें और Ope उसकी उम्मीद करेगा।',
    tourManageEventsTitle: 'प्रचार और कार्यक्रम',
    tourManageEventsBody: 'यहाँ एकबारगी कार्यक्रम और विज्ञापन अभियान टैग करें। Ope मापता है कि हर एक ने वास्तव में कितना अतिरिक्त व्यापार लाया।',
    tourManageSimpleLangTitle: 'सरल भाषा मोड',
    tourManageSimpleLangBody: 'प्रबंधन → सेटिंग्स में "सरल भाषा" टॉगल मिलेगा। इसे चालू करें और Ope तकनीकी शब्दों — जैसे "MAPE", "सुरक्षा बफर", या "FIFO" — को सरल रोज़मर्रा के शब्दों से बदल देगा।',
    tourSectionPreferences: 'प्राथमिकताएं', tourDarkModeTitle: 'अपना लुक चुनें — डार्क या लाइट?',
    tourDarkModeBody: 'Ope लाइट और डार्क दोनों मोड में काम करता है। हाइलाइट किया बटन दोनों के बीच स्विच करता है — अभी आज़माएं! आप कभी भी वापस स्विच कर सकते हैं।',
    tourFriendlyModeTitle: 'सरल शब्दावली पसंद करते हैं?',
    tourFriendlyModeBody: 'हाइलाइट किया टॉगल सरल भाषा मोड चालू करता है, जो तकनीकी शब्दों को सरल रोज़मर्रा के शब्दों से बदलता है। अभी आज़माएं — आप इसे कभी भी बंद कर सकते हैं।',
    tourSettingsGearTitle: 'आपकी सेटिंग्स — हमेशा एक क्लिक दूर',
    tourSettingsGearBody: 'ऊपरी बार में गियर आइकन किसी भी स्क्रीन से सेटिंग्स खोलता है। यहाँ आप अपना खुलने का शेड्यूल, स्टाफिंग लक्ष्य, दिखावट, Telegram और प्लान सेट करते हैं।',
    tourSettingsScheduleTitle: 'आपका खुलने का शेड्यूल',
    tourSettingsScheduleBody: 'Ope को बताएं आप कौन से दिन खुले हैं और खुलने-बंद होने का समय। यह महत्वपूर्ण है — जो दिन आप बंद के रूप में चिह्नित करते हैं वे पूर्वानुमान से पूरी तरह छोड़ दिए जाते हैं।',
    tourSettingsStaffingTitle: 'स्टाफिंग लक्ष्य',
    tourSettingsStaffingBody: 'आपके लिए कितनी प्रतीक्षा स्वीकार्य है? अधिकतम प्रतीक्षा समय या लाइन में अधिकतम लोग सेट करें। Ope इसका उपयोग करके आपको बताता है कि हर घंटे कितने स्टाफ शेड्यूल करने हैं।',
    tourSettingsStockNudgesTitle: 'स्टॉक प्रबंधन',
    tourSettingsStockNudgesBody: 'सभी उत्पादों के लिए इन्वेंटरी ट्रैक करने और आपकी बिक्री गति और सप्लायर लीड टाइम के आधार पर ऑर्डरिंग सलाह पाने के लिए स्टॉक प्रबंधन चालू करें।',
    tourSettingsNudgesTitle: 'सक्रिय सूचनाएं',
    tourSettingsNudgesBody: 'सूचनाएं सबसे महत्वपूर्ण एक बात भेजती हैं — असामान्य रूप से व्यस्त आने वाला दिन, या कम होने वाला स्टॉक — केवल वास्तविक कारण होने पर। यहाँ वे कितनी बार भेज सकती हैं इसे समायोजित करें।',
    tourSettingsAppearanceTitle: 'डार्क मोड और सरल भाषा',
    tourSettingsAppearanceBody: 'यहाँ डार्क और लाइट मोड के बीच स्विच करें। आप सरल भाषा मोड भी चालू कर सकते हैं — यह हर तकनीकी शब्द को सरल रोज़मर्रा के शब्द से बदल देता है।',
    tourSettingsPlanTitle: 'आपका प्लान',
