    // Guided product tour
    tourWelcomeTitle: 'Bienvenue sur Ope !',
    tourWelcomeBody: "Ope vous aide à savoir à quel point votre entreprise sera occupée — pour commander le bon stock, planifier le bon personnel, et ne jamais être pris au dépourvu. Faisons un tour rapide de ce qui est ici.",
    tourQuickActionsTitle: 'Vos actions rapides',
    tourQuickActionsBody: "Ces trois boutons sont vos outils quotidiens. « Enregistrer une vente » compte chaque vente en temps réel. « Enregistrer aujourd'hui » saisit les totaux du jour après la fermeture. « Enregistrer un habitué » note la visite d'un client fidèle.",
    tourForecastTitle: 'Votre prévision de demande',
    tourForecastBody: "Une fois quelques jours enregistrés, ce graphique montre à quel point chaque jour de la semaine à venir sera probablement chargé — pour que vous puissiez planifier à l'avance. Il devient plus précis à mesure que vous enregistrez.",
    tourBusyHoursTitle: "Heures d'affluence",
    tourBusyHoursBody: "Ici, vous verrez quelles heures demain devraient être les plus chargées et combien de personnel vous pourriez avoir besoin au pic. Il utilise les données tapotement par tapotement que vous enregistrez avec « Enregistrer une vente ».",
    tourPredictionsTitle: 'Prévisions',
    tourPredictionsBody: "L'onglet Prévisions montre votre prévision hebdomadaire en détail, ainsi que quoi commander pour chaque produit et quand. Ope apprend vos habitudes et met à jour cela automatiquement à mesure que vous enregistrez plus de jours.",
    tourInsightsTitle: "Aperçus — ce qu'Ope a appris",
    tourInsightsBody: "Cet écran montre ce qu'Ope a compris de votre entreprise à partir de vos données réelles : votre jour le plus chargé, vos heures de pointe, la croissance année après année, et des alertes précoces sur ce qui change.",
    tourHistoryTitle: 'Historique',
    tourHistoryBody: "Sous Historique, vous pouvez consulter tous vos jours passés enregistrés, ajouter un jour oublié, voir les tendances mensuelles, ou importer toute une feuille de calcul de données passées en une fois.",
