    // Predictions section sub-steps
    tourPredWeekTitle: 'Votre prévision hebdomadaire, en détail',
    tourPredWeekBody: "Ici, vous voyez chaque jour à venir sous forme de barre — plus haute veut dire plus chargé. Survolez une barre pour voir la plage attendue (l'écart entre une version plus calme et plus chargée de ce jour). Ope combine plusieurs méthodes de prévision et s'appuie automatiquement sur celle qui a été la plus fiable récemment pour votre entreprise.",
    tourPredOrderingTitle: 'Quoi commander — par produit',
    tourPredOrderingBody: "Faites défiler pour voir les conseils de commande pour chacun de vos produits. Une fois des ventes enregistrées, Ope calcule combien vous aurez besoin avant l'arrivée de votre prochaine livraison et vous dit exactement quand recommander. Vert veut dire que le stock est ok ; rouge veut dire commander maintenant. Appuyez sur « J'ai commandé ceci » quand vous passez une commande et Ope suivra l'arrivée.",

    // Insights section sub-steps
    tourInsightsDayPatternsTitle: 'Votre habitude par jour de la semaine',
    tourInsightsDayPatternsBody: "Voyez quel jour de la semaine est habituellement le plus chargé et lequel est le plus calme, selon vos propres données — pas une supposition. À mesure que vous enregistrez plus de jours, ces habitudes deviennent plus fiables. C'est l'une des premières choses qu'Ope apprend sur votre entreprise.",
    tourInsightsHoursTitle: 'Vos heures de pointe',
    tourInsightsHoursBody: "Une fois que vous avez utilisé « Enregistrer une vente » pendant quelques semaines, Ope montre vos heures les plus chargées et les plus calmes de la journée. Utilisez cela pour planifier le temps de préparation, les pauses du personnel, ou savoir quand vous aurez besoin de tout le monde.",
    tourInsightsYoYTitle: 'Comparaison année après année',
    tourInsightsYoYBody: "Une fois que vous avez un an d'historique, Ope compare ce mois-ci au même mois l'an dernier — pour que vous sachiez si votre entreprise grandit, se maintient, ou décline, sans faire les calculs vous-même. Il vous avertit aussi à l'avance si une saison historiquement chargée approche.",
    tourInsightsAccuracyTitle: 'Fiabilité des prévisions dans le temps',
    tourInsightsAccuracyBody: "Cela montre à quel point vos prévisions sont devenues fiables. Ope commence généralement de façon approximative et s'améliore en apprenant vos habitudes — vous verrez l'amélioration ici en pourcentage réel. Plus l'erreur est faible, plus vous pouvez compter sur la prévision pour les décisions de commande et d'effectifs.",
    tourInsightsTrendsTitle: 'Changements à noter',
    tourInsightsTrendsBody: "Ce sont des choses qui changent VRAIMENT — un jour de la semaine qui augmente ou diminue depuis trois mois, un client fidèle devenu silencieux, ou une saison chargée qui approche. C'est la partie que la plupart des propriétaires manqueraient sans que l'application ne la surveille pour eux.",

    // History section sub-steps
    tourHistAddDayTitle: 'Ajouter un jour passé',
    tourHistAddDayBody: "Oublié d'enregistrer hier ? Utilisez « Ajouter un jour passé » pour remplir tout jour manqué. Choisissez la date dans le calendrier, saisissez le nombre de clients et ce que vous avez vendu, et il rejoint votre historique. Un historique complet veut dire des prévisions plus précises — même une semaine de rattrapage peut faire une différence notable.",
    tourHistTrendsTitle: 'Tendances mensuelles',
    tourHistTrendsBody: "Voyez vos données réparties par mois — clients moyens par jour, totaux, et comment chaque mois se compare au précédent. Utile pour repérer votre saison la plus chargée ou une période calme que vous n'aviez pas consciemment remarquée.",
    tourHistImportTitle: 'Importer des données passées',
    tourHistImportBody: "Vous avez des données dans une feuille de calcul ? Téléchargez un fichier CSV ici pour importer des mois ou années d'historique en une fois — pour ne pas repartir de zéro. Ope prévisualise d'abord le fichier pour que vous vérifiiez que les dates semblent correctes avant d'enregistrer quoi que ce soit.",

    // Manage section sub-steps
    tourManageProductsTitle: 'Mes produits',
    tourManageProductsBody: "Ajoutez ici chaque article que vous vendez — juste un nom et une unité pour commencer (ex. « Pain au levain, pièce »). Ajoutez éventuellement le délai fournisseur, le stock actuel, et la durée de conservation. Une fois un produit ajouté, Ope suit la demande par produit et vous dit quand recommander.",
    tourManageRegularsTitle: 'Mes habitués',
    tourManageRegularsBody: "Ajoutez vos clients fidèles comme « habitués » pour suivre leur fréquence de visite et combien ils valent pour votre entreprise dans le temps. Ope vous avertira si un habitué n'est pas venu depuis un moment — un signal discret qu'il pourrait s'éloigner. Leurs visites ne se mélangent jamais avec votre historique de demande.",
    tourManageRecurringTitle: 'Modèles récurrents',
    tourManageRecurringBody: "Y a-t-il une sortie scolaire chaque dimanche ? Un jour de marché qui apporte toujours plus de clients ? Déclarez-le ici et Ope l'attendra — cela arrête de signaler ce jour comme inhabituel et intègre la hausse dans votre prévision normale. Plus vous enseignez de modèles à Ope, plus il devient intelligent sur votre univers.",
    tourManageEventsTitle: 'Promos et événements',
    tourManageEventsBody: "Marquez ici des événements ponctuels et des campagnes publicitaires — un festival local, une promotion sur les réseaux sociaux, une distribution de flyers. Ope mesure combien d'activité supplémentaire chacun vous a réellement apportée, par rapport à ce que vous attendriez normalement. Idéal pour savoir quelles promotions valent la peine d'être répétées.",
    tourManageSimpleLangTitle: 'Mode langage simple',
    tourManageSimpleLangBody: "Sous Gérer → Paramètres, vous trouverez un interrupteur « Langage simple ». Activez-le et Ope remplace les termes techniques — comme « MAPE », « marge de sécurité », ou « FIFO » — par des mots simples du quotidien. Utile si un libellé semble peu familier. L'anglais et l'hébreu ont tous deux la version simple. La visite guidée elle-même utilise aussi la formulation plus simple quand ce mode est activé.",

