    tourSettingsStaffingTitle: "Objectif d'effectifs",
    tourSettingsStaffingBody: "Combien de temps d'attente vous convient-il ? Définissez un temps d'attente maximum ou un nombre maximum de personnes en file. Ope utilise cela, avec vos données de vente tapotement par tapotement, pour vous dire exactement combien de personnel planifier à chaque heure de la journée.",
    tourSettingsStockNudgesTitle: 'Gestion des stocks',
