    // Guided product tour
    tourWelcomeTitle: 'Ope-তে স্বাগতম!',
    tourWelcomeBody: 'Ope আপনাকে জানতে সাহায্য করে আপনার ব্যবসা কতটা ব্যস্ত থাকবে — যাতে আপনি সঠিক মজুদ অর্ডার করতে পারেন, সঠিক কর্মী নির্ধারণ করতে পারেন, এবং কখনো অপ্রস্তুত না হন। চলুন এখানে কী আছে তা দ্রুত দেখে নিই।',
    tourQuickActionsTitle: 'আপনার দ্রুত কর্ম',
    tourQuickActionsBody: 'এই তিনটি বোতাম আপনার দৈনন্দিন সরঞ্জাম। "বিক্রয় রেকর্ড করুন" প্রতিটি বিক্রয় বাস্তব সময়ে গণনা করে। "আজকের হিসাব লগ করুন" বন্ধ করার পর আজকের মোট হিসাব লিখে। "নিয়মিত গ্রাহক রেকর্ড করুন" একজন বিশ্বস্ত গ্রাহকের ভ্রমণ নোট করে।',
    tourForecastTitle: 'আপনার চাহিদার পূর্বাভাস',
    tourForecastBody: 'কয়েক দিন লগ করার পর, এই চার্টটি দেখায় আগামী সপ্তাহের প্রতিটি দিন কতটা ব্যস্ত হতে পারে — যাতে আপনি আগে থেকে পরিকল্পনা করতে পারেন। যত বেশি লগ করবেন এটি তত বেশি নির্ভুল হবে।',
    tourBusyHoursTitle: 'ব্যস্ত সময়',
    tourBusyHoursBody: 'এখানে আপনি দেখবেন আগামীকাল কোন সময়গুলো সবচেয়ে ব্যস্ত হতে পারে এবং সর্বোচ্চ সময়ে কতজন কর্মী প্রয়োজন হতে পারে। এটি "বিক্রয় রেকর্ড করুন" দিয়ে আপনার রেকর্ড করা ট্যাপ-বাই-ট্যাপ ডেটা ব্যবহার করে।',
    tourPredictionsTitle: 'পূর্বাভাস',
    tourPredictionsBody: 'পূর্বাভাস ট্যাব আপনার সাপ্তাহিক পূর্বাভাস বিস্তারিতভাবে দেখায়, সাথে প্রতিটি পণ্যের জন্য কী ও কখন অর্ডার করতে হবে তাও। Ope আপনার প্যাটার্ন শেখে এবং আপনি যত বেশি দিন লগ করবেন তত স্বয়ংক্রিয়ভাবে এগুলো আপডেট করে।',
    tourInsightsTitle: 'অন্তর্দৃষ্টি — Ope যা শিখেছে',
    tourInsightsBody: 'এই স্ক্রিনটি দেখায় Ope আপনার প্রকৃত ডেটা থেকে আপনার ব্যবসা সম্পর্কে কী বের করেছে: আপনার সবচেয়ে ব্যস্ত দিন, সর্বোচ্চ সময়, বছরের-পর-বছর প্রবৃদ্ধি, এবং পরিবর্তনশীল বিষয়ে প্রাথমিক সতর্কতা।',
    tourHistoryTitle: 'ইতিহাস',
    tourHistoryBody: 'ইতিহাসের অধীনে, আপনি আপনার সব অতীতের লগ করা দিন দেখতে পারেন, ভুলে যাওয়া একটি দিন যোগ করতে পারেন, মাসিক প্রবণতা দেখতে পারেন, অথবা একবারে অতীতের ডেটার একটি পুরো স্প্রেডশিট আমদানি করতে পারেন।',
    tourManageTitle: 'পরিচালনা',
    tourManageBody: 'পরিচালনার অধীনে আপনি পাবেন আপনার পণ্য, বিশ্বস্ত নিয়মিত গ্রাহক, পুনরাবৃত্ত প্যাটার্ন, প্রচার, এবং সেটিংস। এখানেই আপনি Ope-কে আপনার ব্যবসা সম্পর্কে শেখান — যত বেশি যোগ করবেন, এটি তত বুদ্ধিমান হবে।',
    tourDoneTitle: 'আপনি প্রস্তুত!',
    tourDoneBody: 'আপনি যত বেশি লগ করবেন Ope তত বুদ্ধিমান হবে। আজকের বিক্রয় রেকর্ড করে শুরু করুন — তারপর কয়েক সপ্তাহ পরে আপনার প্রথম পূর্বাভাস দেখতে ফিরে আসুন। আপনি সেটিংস থেকে যেকোনো সময় এই ট্যুরটি আবার দেখতে পারেন।',
