    tourSettingsScheduleBody: 'Ope کو بتائیں کہ آپ کن دنوں کھلے ہیں اور آپ کے کھلنے اور بند ہونے کے اوقات کیا ہیں۔ یہ اہم ہے — جن دنوں کو آپ بند نشان زد کرتے ہیں وہ پیشگوئی کی طرف سے مکمل طور پر چھوڑ دیے جاتے ہیں، اور آپ کے کاروباری اوقات سے باہر کے اوقات کو مکمل طور پر نظر انداز کیا جاتا ہے۔ اسے پہلے درست کریں اور باقی سب کچھ بہتر ہو جائے گا۔',
    tourSettingsStaffingTitle: 'اسٹافنگ ہدف',
    tourSettingsStaffingBody: 'آپ کے لیے کتنی لمبی قطار قابل قبول ہے؟ زیادہ سے زیادہ انتظار کا وقت یا قطار میں زیادہ سے زیادہ لوگوں کی تعداد مقرر کریں۔ Ope اسے، آپ کے ٹیپ بہ ٹیپ فروخت کے ڈیٹا کے ساتھ، یہ بتانے کے لیے استعمال کرتا ہے کہ دن کے ہر گھنٹے میں بالکل کتنے عملے کو شیڈول کریں۔',
    tourSettingsStockNudgesTitle: 'اسٹاک کا انتظام',
    tourSettingsStockNudgesBody: 'اپنی تمام مصنوعات کے لیے انوینٹری ٹریک کرنے اور اپنی فروخت کی رفتار اور سپلائر لیڈ ٹائم کی بنیاد پر دوبارہ آرڈر کا مشورہ حاصل کرنے کے لیے اسٹاک کا انتظام آن کریں۔ اگر آپ کو صرف پیشگوئی چاہیے بغیر اسٹاک ٹریکنگ کے تو اسے آف کریں۔',
    tourSettingsNudgesTitle: 'فعال اطلاعات',
    tourSettingsNudgesBody: 'اطلاعات آپ کو وہ ایک چیز بھیجتی ہیں جس پر عمل کرنا اہم ہو — آنے والا غیر معمولی طور پر مصروف دن، یا اسٹاک ختم ہونے والا — ٹیلیگرام اور ایپ کے اندر۔ یہ صرف اسی وقت متحرک ہوتی ہیں جب کوئی حقیقی وجہ ہو، اس لیے یہ کبھی آپ کو تنگ نہیں کرتیں۔ یہاں ٹیون کریں کہ یہ کتنی بار چل سکتی ہیں۔',
    tourSettingsAppearanceTitle: 'تاریک موڈ اور سادہ زبان',
    tourSettingsAppearanceBody: 'یہاں تاریک اور روشن موڈ کے درمیان سوئچ کریں۔ آپ سادہ زبان موڈ بھی آن کر سکتے ہیں — یہ ہر تکنیکی اصطلاح کو ایک سادہ روزمرہ لفظ سے بدل دیتا ہے۔ دونوں ترتیبات اگلی بار کے لیے محفوظ ہو جاتی ہیں۔ اگر ایپ میں کچھ کبھی غیر واضح لگے تو ابھی سادہ زبان آن کرنے کی کوشش کریں۔',
    tourSettingsPlanTitle: 'آپ کا پلان',
