    tourPredictionsBody: 'Tab Prediksi menampilkan perkiraan mingguan Anda secara rinci, ditambah apa yang perlu dipesan untuk setiap produk dan kapan. Ope mempelajari pola Anda dan memperbarui ini secara otomatis seiring Anda mencatat lebih banyak hari.',
    tourInsightsTitle: 'Wawasan — apa yang telah dipelajari Ope',
    tourInsightsBody: 'Layar ini menampilkan apa yang telah dipahami Ope tentang bisnis Anda dari data nyata Anda: hari paling ramai, jam puncak, pertumbuhan tahun ke tahun, dan peringatan dini tentang hal-hal yang sedang berubah.',
    tourHistoryTitle: 'Riwayat',
    tourHistoryBody: 'Di bawah Riwayat, Anda bisa melihat semua hari yang telah Anda catat, menambahkan hari yang terlewat, melihat tren bulanan, atau mengimpor seluruh spreadsheet data lama sekaligus.',
    tourManageTitle: 'Kelola',
    tourManageBody: 'Di bawah Kelola Anda akan menemukan produk, pelanggan tetap setia, pola berulang, promo, dan pengaturan. Di sinilah Anda mengajarkan Ope tentang bisnis Anda — semakin banyak Anda tambahkan, semakin pintar Ope jadinya.',
    tourDoneTitle: 'Anda sudah siap!',
    tourDoneBody: 'Ope semakin pintar seiring Anda mencatat. Mulailah dengan mencatat penjualan hari ini — lalu kembali lagi dalam beberapa minggu untuk melihat perkiraan pertama Anda. Anda bisa memutar ulang tur ini kapan saja dari Pengaturan.',
