    firstVisitDateDesc: 'Kapan mereka pertama kali berkunjung? Otomatis diisi pada kunjungan pertama yang tercatat jika dibiarkan kosong.',

    // Simple language mode toggle
    simpleModeLabel: 'Bahasa sederhana',
    simpleModeDesc: 'Mengganti istilah teknis (nama model perkiraan, jargon stok) dengan kata-kata sehari-hari yang sederhana. Cocok jika ada label yang terasa asing.',
    simpleModeOn: 'Bahasa sederhana — aktif',
