    insightsAllRegularsActive: 'Alle Ihre Stammkunden sind aktiv. Großartig!',

    // Guided product tour
    tourWelcomeTitle: 'Willkommen bei Ope!',
    tourWelcomeBody: 'Ope hilft Ihnen zu wissen, wie geschäftig Ihr Betrieb sein wird — damit Sie den richtigen Bestand bestellen, das richtige Personal einplanen und nie überrascht werden. Machen wir eine kurze Tour durch das, was hier ist.',
    tourQuickActionsTitle: 'Ihre Schnellaktionen',
    tourQuickActionsBody: 'Diese drei Buttons sind Ihre täglichen Werkzeuge. „Verkauf erfassen" zählt jeden Verkauf in Echtzeit. „Heute eintragen" trägt die heutigen Summen nach Geschäftsschluss ein. „Stammkunden erfassen" notiert den Besuch eines treuen Kunden.',
    tourForecastTitle: 'Ihre Bedarfsprognose',
    tourForecastBody: 'Sobald Sie ein paar Tage erfasst haben, zeigt dieses Diagramm, wie geschäftig jeder Tag der kommenden Woche voraussichtlich sein wird — damit Sie im Voraus planen können. Es wird umso genauer, je mehr Sie erfassen.',
    tourBusyHoursTitle: 'Stoßzeiten',
    tourBusyHoursBody: 'Hier sehen Sie, welche Stunden morgen voraussichtlich am geschäftigsten sein werden und wie viel Personal Sie zur Spitzenzeit brauchen könnten. Es nutzt die Tipp-für-Tipp-Daten, die Sie mit „Verkauf erfassen" erfassen.',
    tourPredictionsTitle: 'Prognosen',
    tourPredictionsBody: 'Der Tab Prognosen zeigt Ihre Wochenprognose im Detail sowie was für jedes Produkt zu bestellen ist und wann. Ope lernt Ihre Muster und aktualisiert dies automatisch, während Sie mehr Tage erfassen.',
    tourInsightsTitle: 'Einblicke — was Ope gelernt hat',
    tourInsightsBody: 'Dieser Bildschirm zeigt, was Ope aus Ihren realen Daten über Ihr Geschäft herausgefunden hat: Ihr geschäftigster Tag, Spitzenzeiten, Wachstum im Jahresvergleich und frühe Warnungen zu Dingen, die sich verändern.',
    tourHistoryTitle: 'Verlauf',
    tourHistoryBody: 'Unter Verlauf können Sie alle Ihre vergangenen erfassten Tage einsehen, einen vergessenen Tag hinzufügen, Monatstrends ansehen oder eine ganze Tabelle mit vergangenen Daten auf einmal importieren.',
    tourManageTitle: 'Verwalten',
    tourManageBody: 'Unter Verwalten finden Sie Ihre Produkte, treue Stammkunden, wiederkehrende Muster, Aktionen und Einstellungen. Hier bringen Sie Ope Ihr Geschäft bei — je mehr Sie hinzufügen, desto klüger wird es.',
    tourDoneTitle: 'Sie sind startklar!',
    tourDoneBody: 'Ope wird umso klüger, je mehr Sie erfassen. Beginnen Sie damit, die heutigen Verkäufe zu erfassen — schauen Sie dann in ein paar Wochen wieder vorbei, um Ihre erste Prognose zu sehen. Sie können diese Tour jederzeit über die Einstellungen erneut abspielen.',
    tourBack: '← Zurück',
    tourNext: 'Weiter →',
    tourFinish: "Los geht's!",
    tourSkipAll: 'Tour überspringen',
    tourSkipStep: 'Diesen Schritt überspringen',
    tourReplayLabel: 'Geführte Tour',
    tourReplayDesc: 'Sehen Sie sich die geführte Tour durch Ope noch einmal von Anfang an an.',
    tourReplayBtn: 'Tour wiederholen',

    privacyPolicy: 'Datenschutzrichtlinie',

