    // Product status panel (new Manage tab)
    stockStatusTab: 'Produktstatus',
    tabStockStatus: 'Produktbestand & -status',
    stockStatusDesc: 'Alle Produkte mit aktuellem Lagerbestand. Bestellen Sie hier jedes Produkt nach, auch wenn es noch nicht nötig ist.',
    stockStatusEmpty: 'Fügen Sie zunächst Produkte unter Meine Produkte hinzu.',
    allProductsTitle: 'Alle Produkte',

    // Reorder window — focused view
    fullyStockedNote: '{n} weitere Produkt{s} vollständig auf Lager — siehe Produktstatus unter Verwalten für die gesamte Übersicht.',
    nothingToOrder: 'Alle Produkte sind vollständig auf Lager — momentan nichts zu bestellen.',

    // Regulars — first visit date
    firstVisitDateLabel: 'Datum des ersten Besuchs',
    firstVisitDateDesc: 'Wann haben sie zum ersten Mal besucht? Wird beim ersten erfassten Besuch automatisch gesetzt, falls leer gelassen.',

    // Simple language mode toggle
    simpleModeLabel: 'Einfache Sprache',
    simpleModeDesc: 'Ersetzt Fachbegriffe (Prognosemodellnamen, Bestandsjargon) durch einfache Alltagswörter. Praktisch, wenn Ihnen ein Begriff unbekannt vorkommt.',
    simpleModeOn: 'Einfache Sprache — an',
    simpleModeOff: 'Standardformulierung',
    simpleModeHint: 'Tipp: Schalten Sie „Einfache Sprache" in den Einstellungen ein, wenn Ihnen Begriffe verwirrend erscheinen.',

    // Staffing marginal-note i18n (structured, replaces backend English prose)
    marginalNoData: 'Nicht genug Daten, um Personalstufen zu vergleichen.',
    marginalShortQueue: 'Die Warteschlange ist bereits sehr kurz — eine {nth}. Person hätte kaum Wirkung.',
    marginalAddCutsWait: 'Eine {nth}. Person hinzuzufügen verkürzt die Wartezeit von {from} auf {to}.',
    marginalRemoveOverload: '1 Person weniger würde die Warteschlange überlasten — behalten Sie mindestens {servers}.',
    marginalRemovePushes: '1 Person weniger erhöht die Wartezeit auf {to}.',
