    // Guided product tour
    tourWelcomeTitle: "Ope'ye hoş geldiniz!",
    tourWelcomeBody: "Ope, işletmenizin ne kadar yoğun olacağını bilmenize yardımcı olur — böylece doğru stoğu sipariş edebilir, doğru personeli planlayabilir ve asla hazırlıksız yakalanmazsınız. Burada neler olduğuna hızlıca bir bakalım.",
    tourQuickActionsTitle: 'Hızlı işlemleriniz',
    tourQuickActionsBody: 'Bu üç düğme günlük araçlarınızdır. "Satış Kaydet" her satışı gerçek zamanlı olarak sayar. "Bugünü Kaydet" kapandıktan sonra bugünün toplamlarını girer. "Müdavim Kaydet" sadık bir müşterinin ziyaretini not eder.',
    tourForecastTitle: 'Talep tahmininiz',
    tourForecastBody: "Birkaç gün kaydettikten sonra, bu grafik önümüzdeki haftanın her gününün ne kadar yoğun olabileceğini gösterir — böylece önceden plan yapabilirsiniz. Ne kadar çok kaydederseniz o kadar doğru olur.",
    tourBusyHoursTitle: 'Yoğun saatler',
    tourBusyHoursBody: 'Burada yarın hangi saatlerin en yoğun olması beklendiğini ve zirve zamanda kaç personele ihtiyacınız olabileceğini göreceksiniz. "Satış Kaydet" ile kaydettiğiniz dokunma verilerini kullanır.',
    tourPredictionsTitle: 'Tahminler',
    tourPredictionsBody: "Tahminler sekmesi, haftalık tahmininizi ayrıntılı olarak ve her ürün için ne zaman ne sipariş edileceğini gösterir. Ope desenlerinizi öğrenir ve daha fazla gün kaydettikçe bunları otomatik olarak günceller.",
    tourInsightsTitle: "İçgörüler — Ope'nin öğrendikleri",
    tourInsightsBody: "Bu ekran, Ope'nin gerçek verilerinizden işletmeniz hakkında çözdüklerini gösterir: en yoğun gününüz, zirve saatleriniz, yıldan yıla büyüme ve değişen şeyler hakkında erken uyarılar.",
    tourHistoryTitle: 'Geçmiş',
    tourHistoryBody: "Geçmiş altında, tüm geçmiş kaydedilen günlerinizi görebilir, unuttuğunuz bir günü ekleyebilir, aylık trendleri görebilir veya geçmiş verilerin tamamını bir elektronik tablodan tek seferde içe aktarabilirsiniz.",
    tourManageTitle: 'Yönet',
    tourManageBody: "Yönet altında ürünlerinizi, sadık müdavimlerinizi, tekrarlayan desenlerinizi, promosyonlarınızı ve ayarlarınızı bulacaksınız. Burası Ope'ye işletmeniz hakkında bilgi verdiğiniz yerdir — ne kadar çok eklerseniz o kadar akıllanır.",
